# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
B=[['拉丁 in- + gnarus → ignarus／ignorare','不 + 知道 → 不知道；不理会'],['法语 ignorer → 英语 ignore','最初有不知道义，现代常指不予理会']]
W=[
E('ignore','英 /ɪɡˈnɔː/；美 /ɪɡˈnɔːr/','不理会、忽视','明明有这件事，却不把注意力或行动放过去。','经法语 ignorer 或直接来自拉丁 ignorare；更早是表示否定的 in- 与“知道”一族的结合。现代不是 i + gnore。',B,'朋友问话你不回应、设备报警却继续操作，都可以用 ignore。它通常强调不予注意或不处理；有时是故意，有时是未充分重视，不能单靠这个词就断言动机。英语早期也有“不知道”义，现代普通用法已偏向“不理会”。','ignore a warning；ignore someone；ignore the fact that。','be ignorant of 是不知道某事，ignore 往往是没有理会它。说 I ignored the rule 通常不像 I didn’t know the rule 那样是在解释“不知情”。',('Please ignore the previous message; it contained the wrong address.','请忽略上一条消息，里面的地址写错了。'),('He ignored my question and changed the subject.','他没有理会我的问题，转而谈起了别的事。'),sources=['https://www.etymonline.com/word/ignore','https://en.wiktionary.org/wiki/ignore']),
E('ignorance','/ˈɪɡnərəns/','无知；不了解、不知情','脑中的信息缺了一块，还没有弄清实际情况。','由古法语 ignorance 借入，来自拉丁 ignorantia；与 ignorant 同族，英语中出现早于现代 ignore，不是给“不理会”机械加后缀。',[['拉丁 ignorare → ignorantia','不知道 → 缺少了解的状态'],['古法语 ignorance → 英语 ignorance','无知、不知情']],'ignorance of local customs 是不了解当地习俗，不等于智力低下。admit your ignorance 是承认自己不知道；kept in ignorance 则是别人没有把情况告诉你。这个名词说的是知识状态，并不直接等于故意冷落人的行为。','ignorance of；in ignorance；admit ignorance；out of ignorance。','ignorance 主要是“不知道”；ignoring 是“不理会”的行为。两者同源，现代含义却不能当成一个动作与其名词的简单对应。',('I made the mistake out of ignorance, not because I wanted to cause trouble.','我犯这个错是因为不了解情况，并不是想惹麻烦。'),('The staff were kept in ignorance of the planned changes.','员工一直没有被告知计划中的变化。'),sources=['https://www.etymonline.com/word/ignorance','https://en.wiktionary.org/wiki/ignorance']),
E('ignored','英 /ɪɡˈnɔːd/；美 /ɪɡˈnɔːrd/','忽视了；被忽略的、不受理会的','发出的信号没有被接住，或没有得到回应。','ignore 加 -d，构成过去式和过去分词；-ed 这里读 /d/，不另读一拍 /ɪd/。',B+[['英语 ignore → ignored','不理会 → 已不理会；被忽略']],'She ignored me 是她没理我；I felt ignored 是我觉得自己被冷落了。前者报告动作，后者报告感受，不一定已经证明别人故意排斥自己。被动句 the warning was ignored 则把重点放在警告没有受到重视。','feel ignored；be ignored；an ignored warning。','ignored 是没有得到注意；forgotten 是被遗忘。一个问题可以被记得很清楚，却一直被 ignored。',('Her suggestion was ignored during the meeting.','她的建议在会上没有得到理会。'),('I felt ignored when nobody responded to my question.','没有人回应我的问题时，我感到自己被冷落了。'),sources=['https://en.wiktionary.org/wiki/ignored','https://en.wiktionary.org/wiki/ignore']),
E('ignoring','英 /ɪɡˈnɔːrɪŋ/；美 /ɪɡˈnɔːrɪŋ/','正在忽视；不理会这一行为','事情摆在面前，注意力却从它旁边绕过去。','ignore 去末尾不发音 e 加 -ing；可作现在分词或动名词。即使英音 ignore 末尾不发 r，接元音词尾时这里的 r 仍读出来。',B+[['英语 ignore + -ing → ignoring','不理会的持续动作或这一行为']],'Are you ignoring me? 问的是“你是不是不理我”，不是“你是不是不认识我”。Ignoring the problem won’t help 里整个 -ing 短语作主语，表示“不去处理问题”这种做法。','keep ignoring；stop ignoring；ignoring the problem。','ignoring 指行为，ignorant 指不了解的状态；He is ignoring the warning 与 He is ignorant of the warning 讲的是不同情况。',('Ignoring the leak will only make the damage worse.','不管漏水问题，只会让损坏更严重。'),('She was not ignoring you; she could not hear the question.','她不是不理你，而是没听见问题。'),sources=['https://en.wiktionary.org/wiki/ignoring','https://en.wiktionary.org/wiki/ignore'])]
ROOT=dict(id='C0599',meaning='不知道；后来发展出不理会',core='IGNOR = NOT KNOW / DISREGARD',image='一条信息可能根本没进入你的脑中，也可能已经摆到你面前，却被你放到一边。ignorance 与 ignore 如今分别偏向这两个场景。',intro='这族来自拉丁 ignorare“不知道、不理会”，更早联系否定成分与“知道”的词族。它最值得学的不是多背几个长词，而是分清不知道与不理会：ignorant／ignorance 通常讲不了解，ignore／ignored／ignoring 通常讲没有给予注意或回应。',forms='ignorant、ignorance 是历史上分别借入的同族词，不要都画成英语 ignore 现场加后缀。ignored 是 ignore 的过去式与过去分词，ignoring 是 -ing 形式；ignorantly 则是 ignorant + -ly。',branches=[['没有理会或处理','ignore, ignored, ignoring'],['缺少了解或知识','ignorant, ignorance, ignorantly']],contrasts='不知道警告存在，与知道却没理会，责任和场景都不一样。ignore 通常比 miss“没注意到”更强调不予注意，但不能离开上下文就断言所有 ignore 都是蓄意行为。',practice='He was ignorant of the new rule; he was not deliberately ignoring it.\n\n他不知道新规定，并不是故意不遵从。',words=[w['word'] for w in W]+['ignorant','ignorantly'],exclude={'iggy':'较局限的俚语缩略形式，按学习优先级暂略'})
if __name__=='__main__':
 for name,data in [('roots_ignore',[ROOT]),('words_ignore',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(w['examples']) for w in W))
